package dev.filmroom.engine

import org.junit.Assert.*
import org.junit.Test
import java.io.File
import java.io.IOException
import java.util.concurrent.CancellationException
import java.util.zip.DeflaterOutputStream
import java.io.ByteArrayOutputStream

class PackedSpectralLutTest {
    private fun packed()=File(System.getProperty("filmroom.lut.packed")).readBytes()
    private fun original()=File(System.getProperty("filmroom.lut.original")).readBytes()
    private fun rejected(bytes:ByteArray){try{PackedSpectralLut.decode(bytes.inputStream());fail("accepted corrupt asset")}catch(expected:IOException){assertEquals("本地光谱资料校验失败",expected.message)}}
    @Test fun actualOriginalNpyAndEveryFloatBitRoundTrips(){assertArrayEquals(original(),PackedSpectralLut.decode(packed().inputStream()))}
    @Test fun rejectMagicAndVersion(){for(i in listOf(0,8)){val b=packed();b[i]=(b[i].toInt() xor 1).toByte();rejected(b)}}
    @Test fun rejectLengthHeaderStrideAndSha(){for(i in listOf(12,16,20,24,152)){val b=packed();b[i]=(b[i].toInt() xor 1).toByte();rejected(b)}}
    @Test fun rejectTruncation(){val b=packed();for(n in listOf(0,24,184,b.size/2,b.size-1))rejected(b.copyOf(n))}
    @Test fun rejectTrailingAndOversizedInput(){rejected(packed()+byteArrayOf(0));rejected(ByteArray(3_000_001))}
    @Test fun rejectCompressedBitFlip(){val b=packed();b[200]=(b[200].toInt() xor 64).toByte();rejected(b)}
    @Test fun rejectValidZlibWrongDecodedSha(){val b=packed();val plain=java.util.zip.InflaterInputStream(b.copyOfRange(184,b.size).inputStream()).readBytes();plain[100]=(plain[100].toInt() xor 1).toByte();val o=ByteArrayOutputStream();o.write(b,0,184);DeflaterOutputStream(o).use{it.write(plain)};rejected(o.toByteArray())}
    @Test fun rejectExpansionBeyondFixedOutput(){val b=packed();val o=ByteArrayOutputStream();o.write(b,0,184);DeflaterOutputStream(o).use{it.write(ByteArray(5_972_096))};rejected(o.toByteArray())}
    @Test fun cancelledBeforeAndDuringDecode(){for(limit in listOf(1,50,150)){var calls=0;try{PackedSpectralLut.decode(packed().inputStream()){if(++calls>=limit)throw CancellationException()};fail()}catch(expected:CancellationException){}}}
    @Test fun atomicInstallAndExistingGoodCopyReused(){val dir=kotlin.io.path.createTempDirectory().toFile();try{val dest=File(dir,"lut.npy");PackedSpectralLut.install(packed().inputStream(),dest,dir);assertArrayEquals(original(),dest.readBytes());PackedSpectralLut.install(packed().inputStream(),dest,dir,replace={_,_->throw AssertionError("should reuse")});assertEquals(listOf("lut.npy"),dir.list()!!.toList())}finally{dir.deleteRecursively()}}
    @Test fun corruptUpdatePreservesOldGoodCopy(){val dir=kotlin.io.path.createTempDirectory().toFile();try{val dest=File(dir,"lut.npy");val old=original();dest.writeBytes(old);try{PackedSpectralLut.install(byteArrayOf(1).inputStream(),dest,dir);fail()}catch(expected:IOException){};assertArrayEquals(old,dest.readBytes());assertEquals(1,dir.list()!!.size)}finally{dir.deleteRecursively()}}
    @Test fun failedAtomicReplacementPreservesOldAndCleansTemporary(){val dir=kotlin.io.path.createTempDirectory().toFile();try{val dest=File(dir,"lut.npy");val old=byteArrayOf(1,2);dest.writeBytes(old);try{PackedSpectralLut.install(packed().inputStream(),dest,dir,replace={_,_->false});fail()}catch(expected:IOException){};assertArrayEquals(old,dest.readBytes());assertEquals(1,dir.list()!!.size)}finally{dir.deleteRecursively()}}
    @Test fun cancellationBeforeFirstTemporaryWritePreservesOldAndCleans(){val dir=kotlin.io.path.createTempDirectory().toFile();try{val dest=File(dir,"lut.npy");dest.writeBytes(byteArrayOf(9));try{PackedSpectralLut.install(packed().inputStream(),dest,dir,checkCancelled={if(dir.list()!!.any{it.endsWith(".tmp")})throw CancellationException()});fail()}catch(expected:CancellationException){};assertArrayEquals(byteArrayOf(9),dest.readBytes());assertEquals(1,dir.list()!!.size)}finally{dir.deleteRecursively()}}
    @Test fun failedDiskParentDoesNotReplaceOld(){val dir=kotlin.io.path.createTempDirectory().toFile();try{val blocker=File(dir,"blocked");blocker.writeText("old");try{PackedSpectralLut.install(packed().inputStream(),File(blocker,"lut.npy"),dir);fail()}catch(expected:IOException){};assertEquals("old",blocker.readText());assertEquals(1,dir.list()!!.size)}finally{dir.deleteRecursively()}}
    @Test fun symlinkDestinationRejectedWithoutTouchingTarget(){val dir=kotlin.io.path.createTempDirectory().toFile();try{val target=File(dir,"target.npy");val old=original();target.writeBytes(old);val link=File(dir,"link.npy");java.nio.file.Files.createSymbolicLink(link.toPath(),target.toPath());try{PackedSpectralLut.install(packed().inputStream(),link,dir);fail()}catch(expected:IOException){};assertArrayEquals(old,target.readBytes());assertTrue(java.nio.file.Files.isSymbolicLink(link.toPath()));assertEquals(2,dir.list()!!.size)}finally{dir.deleteRecursively()}}
    @Test fun generatedAssetsDoNotDuplicateOriginal(){val transport=File(System.getProperty("filmroom.lut.packed"));assertTrue(transport.isFile);assertFalse(File(transport.parentFile,PackedSpectralLut.ORIGINAL_NAME).exists());assertTrue(File(System.getProperty("filmroom.lut.original")).isFile)}
    @Test fun nestedParentSymlinkRejectedAndTrustedRootAliasAccepted(){val dir=kotlin.io.path.createTempDirectory().toFile();try{val root=File(dir,"root").apply{mkdir()};val outside=File(dir,"outside").apply{mkdir()};val bad=File(root,"nested");java.nio.file.Files.createSymbolicLink(bad.toPath(),outside.toPath());try{PackedSpectralLut.install(packed().inputStream(),File(bad,"lut.npy"),root);fail()}catch(expected:IOException){};assertTrue(outside.list()!!.isEmpty());val alias=File(dir,"alias");java.nio.file.Files.createSymbolicLink(alias.toPath(),root.toPath());val installed=PackedSpectralLut.install(packed().inputStream(),File(alias,"ok.npy"),alias);assertArrayEquals(original(),installed.readBytes());assertEquals(File(root,"ok.npy").canonicalFile,installed)}finally{dir.deleteRecursively()}}
    @Test fun cancelledAfterFullTemporaryWriteCleansAndPreserves(){checkFullTempFailure(false,false)}
    @Test fun corruptedTemporaryFileNeverCommitted(){checkFullTempFailure(true,false)}
    @Test fun cancellationAfterTemporaryShaBeforeRename(){checkFullTempFailure(false,true)}
    private fun checkFullTempFailure(corrupt:Boolean,late:Boolean){val dir=kotlin.io.path.createTempDirectory().toFile();try{val dest=File(dir,"lut.npy");dest.writeBytes(byteArrayOf(7));var checks=0;var mutated=false;try{PackedSpectralLut.install(packed().inputStream(),dest,dir,checkCancelled={val tmp=dir.listFiles()!!.firstOrNull{it.name.endsWith(".tmp")};if(tmp?.length()==PackedSpectralLut.ORIGINAL_BYTES.toLong()){checks++;if(corrupt){if(!mutated){java.io.RandomAccessFile(tmp,"rw").use{it.seek(200);it.write(255)};mutated=true}}else if(!late || checks>((PackedSpectralLut.ORIGINAL_BYTES+65535)/65536)+2)throw CancellationException()}},replace={_,_->throw AssertionError("must not rename")});fail()}catch(expected:CancellationException){assertFalse(corrupt)}catch(expected:IOException){assertTrue(corrupt)};assertArrayEquals(byteArrayOf(7),dest.readBytes());assertEquals(1,dir.list()!!.size)}finally{dir.deleteRecursively()}}
    @Test fun temporaryUsesExistingStartupRecoveryNamespace(){val dir=kotlin.io.path.createTempDirectory().toFile();try{try{PackedSpectralLut.install(packed().inputStream(),File(dir,"lut.npy"),dir,replace={temporary,_->assertTrue(temporary.name.matches(Regex("asset-[A-Za-z0-9]+\\.tmp")));false});fail()}catch(expected:IOException){};assertTrue(dir.list()!!.isEmpty())}finally{dir.deleteRecursively()}}
}
